}

.shadow-sm {
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

/* Custom focus ring for better accessibility */
.focus\:ring-2:focus {
    box-shadow: 0 0 0 2px var(--tw-ring-color);
}

/* Animated icons */
